认证（Authentication）和授权（Authorization）是应用安全的核心，ASP.NET Core 提供了灵活的安全框架。

## 认证 vs 授权

**认证**：验证用户身份（"你是谁？"）
- 验证凭据（用户名/密码、Token、证书）
- 创建身份标识（ClaimsPrincipal）

**授权**：验证用户权限（"你能做什么？"）
- 基于角色的授权
- 基于策略的授权
- 基于资源的授权

## JWT 认证

JSON Web Token 是无状态认证的主流方案：
```csharp
// 安装 NuGet 包
// Microsoft.AspNetCore.Authentication.JwtBearer

// 配置 JWT
builder.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme)
    .AddJwtBearer(options =>
    {
        options.TokenValidationParameters = new TokenValidationParameters
        {
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true,
            ValidIssuer = "your-issuer",
            ValidAudience = "your-audience",
            IssuerSigningKey = new SymmetricSecurityKey(
                Encoding.UTF8.GetBytes("your-secret-key"))
        };
    });

// 生成 Token
public string GenerateToken(User user)
{
    var claims = new[]
    {
        new Claim(ClaimTypes.NameIdentifier, user.Id.ToString()),
        new Claim(ClaimTypes.Name, user.Username),
        new Claim(ClaimTypes.Role, user.Role)
    };

    var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_secret));
    var credentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

    var token = new JwtSecurityToken(
        issuer: "your-issuer",
        audience: "your-audience",
        claims: claims,
        expires: DateTime.UtcNow.AddHours(1),
        signingCredentials: credentials);

    return new JwtSecurityTokenHandler().WriteToken(token);
}
```

## Cookie 认证

适用于传统 Web 应用：
```csharp
builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme)
    .AddCookie(options =>
    {
        options.LoginPath = "/Account/Login";
        options.LogoutPath = "/Account/Logout";
        options.AccessDeniedPath = "/Account/AccessDenied";
        options.ExpireTimeSpan = TimeSpan.FromHours(1);
        options.SlidingExpiration = true;
    });

// 登录
public async Task<IActionResult> Login(LoginModel model)
{
    // 验证用户
    var user = await AuthenticateUser(model.Username, model.Password);
    if (user == null)
        return Unauthorized();

    var claims = new List<Claim>
    {
        new Claim(ClaimTypes.Name, user.Username),
        new Claim(ClaimTypes.Role, user.Role)
    };

    var identity = new ClaimsIdentity(claims, CookieAuthenticationDefaults.AuthenticationScheme);
    var principal = new ClaimsPrincipal(identity);

    await HttpContext.SignInAsync(
        CookieAuthenticationDefaults.AuthenticationScheme,
        principal);

    return RedirectToAction("Index", "Home");
}
```

## 授权策略

**基于角色**：
```csharp
[Authorize(Roles = "Admin")]
public IActionResult AdminOnly() { }

[Authorize(Roles = "Admin,Manager")]
public IActionResult AdminOrManager() { }
```

**基于策略**：
```csharp
// 定义策略
builder.Services.AddAuthorization(options =>
{
    options.AddPolicy("AtLeast18", policy =>
        policy.Requirements.Add(new MinimumAgeRequirement(18)));

    options.AddPolicy("CanEditArticle", policy =>
        policy.RequireClaim("permission", "article.edit"));
});

// 使用策略
[Authorize(Policy = "AtLeast18")]
public IActionResult AdultContent() { }
```

**自定义策略处理器**：
```csharp
public class MinimumAgeRequirement : IAuthorizationRequirement
{
    public int MinimumAge { get; }

    public MinimumAgeRequirement(int minimumAge)
    {
        MinimumAge = minimumAge;
    }
}

public class MinimumAgeHandler : AuthorizationHandler<MinimumAgeRequirement>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        MinimumAgeRequirement requirement)
    {
        var birthDate = context.User.FindFirst(ClaimTypes.DateOfBirth);
        if (birthDate != null)
        {
            var age = DateTime.Today.Year - DateTime.Parse(birthDate.Value).Year;
            if (age >= requirement.MinimumAge)
            {
                context.Succeed(requirement);
            }
        }

        return Task.CompletedTask;
    }
}
```

## 基于资源的授权

```csharp
public class ArticleAuthorizationHandler :
    AuthorizationHandler<OperationAuthorizationRequirement, Article>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        OperationAuthorizationRequirement requirement,
        Article resource)
    {
        if (requirement.Name == "Edit")
        {
            if (resource.AuthorId == context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value)
            {
                context.Succeed(requirement);
            }
        }

        return Task.CompletedTask;
    }
}

// 使用
public class ArticleController : ControllerBase
{
    private readonly IAuthorizationService _authorizationService;

    public async Task<IActionResult> Edit(int id, Article article)
    {
        var authResult = await _authorizationService.AuthorizeAsync(
            User, article, new OperationAuthorizationRequirement { Name = "Edit" });

        if (!authResult.Succeeded)
            return Forbid();

        // 更新文章
    }
}
```

## OAuth2 / OpenID Connect

集成第三方登录：
```csharp
builder.Services.AddAuthentication()
    .AddGoogle(options =>
    {
        options.ClientId = "google-client-id";
        options.ClientSecret = "google-client-secret";
    })
    .AddGitHub(options =>
    {
        options.ClientId = "github-client-id";
        options.ClientSecret = "github-client-secret";
    });
```

## JWT vs Cookie 对比

**JWT 优点**：
- 无状态，服务端不需要存储
- 跨域支持好
- 适合 API 和微服务

**Cookie 优点**：
- 自动携带，前端简单
- 支持 HttpOnly，防止 XSS
- 内置过期和滑动过期

**选择建议**：
- SPA + API：JWT
- 传统 MVC：Cookie
- 移动端：JWT

using System;
using System.Collections.Generic;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authentication.JwtBearer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.IdentityModel.Tokens;

namespace AuthenticationAuthorizationDemo
{
    // 用户模型
    public class User
    {
        public int Id { get; set; }
        public string Username { get; set; }
        public string Password { get; set; }
        public string Role { get; set; }
        public DateTime BirthDate { get; set; }
    }

    // JWT 服务
    public class JwtService
    {
        private readonly string _secret;
        private readonly string _issuer;
        private readonly string _audience;

        public JwtService(string secret, string issuer, string audience)
        {
            _secret = secret;
            _issuer = issuer;
            _audience = audience;
        }

        public string GenerateToken(User user)
        {
            var claims = new[]
            {
                new Claim(ClaimTypes.NameIdentifier, user.Id.ToString()),
                new Claim(ClaimTypes.Name, user.Username),
                new Claim(ClaimTypes.Role, user.Role),
                new Claim(ClaimTypes.DateOfBirth, user.BirthDate.ToString("yyyy-MM-dd"))
            };

            var key = new SymmetricSecurityKey(Encoding.UTF8.GetBytes(_secret));
            var credentials = new SigningCredentials(key, SecurityAlgorithms.HmacSha256);

            var token = new JwtSecurityToken(
                issuer: _issuer,
                audience: _audience,
                claims: claims,
                expires: DateTime.UtcNow.AddHours(1),
                signingCredentials: credentials);

            return new JwtSecurityTokenHandler().WriteToken(token);
        }

        public ClaimsPrincipal ValidateToken(string token)
        {
            var tokenHandler = new JwtSecurityTokenHandler();
            var key = Encoding.UTF8.GetBytes(_secret);

            var validationParameters = new TokenValidationParameters
            {
                ValidateIssuer = true,
                ValidateAudience = true,
                ValidateLifetime = true,
                ValidateIssuerSigningKey = true,
                ValidIssuer = _issuer,
                ValidAudience = _audience,
                IssuerSigningKey = new SymmetricSecurityKey(key)
            };

            return tokenHandler.ValidateToken(token, validationParameters, out _);
        }
    }

    // 自定义授权需求和处理器
    public class MinimumAgeRequirement : IAuthorizationRequirement
    {
        public int MinimumAge { get; }

        public MinimumAgeRequirement(int minimumAge)
        {
            MinimumAge = minimumAge;
        }
    }

    public class MinimumAgeHandler : AuthorizationHandler<MinimumAgeRequirement>
    {
        protected override Task HandleRequirementAsync(
            AuthorizationHandlerContext context,
            MinimumAgeRequirement requirement)
        {
            var birthDateClaim = context.User.FindFirst(ClaimTypes.DateOfBirth);
            if (birthDateClaim == null)
            {
                return Task.CompletedTask;
            }

            var birthDate = DateTime.Parse(birthDateClaim.Value);
            var age = DateTime.Today.Year - birthDate.Year;
            if (birthDate > DateTime.Today.AddYears(-age))
            {
                age--;
            }

            if (age >= requirement.MinimumAge)
            {
                context.Succeed(requirement);
            }

            return Task.CompletedTask;
        }
    }

    // 操作授权需求
    public class ArticleOperationAuthorizationHandler :
        AuthorizationHandler<OperationAuthorizationRequirement, Article>
    {
        protected override Task HandleRequirementAsync(
            AuthorizationHandlerContext context,
            OperationAuthorizationRequirement requirement,
            Article resource)
        {
            var userId = context.User.FindFirst(ClaimTypes.NameIdentifier)?.Value;

            switch (requirement.Name)
            {
                case "Edit":
                case "Delete":
                    if (resource.AuthorId == userId)
                    {
                        context.Succeed(requirement);
                    }
                    break;

                case "View":
                    context.Succeed(requirement);
                    break;
            }

            return Task.CompletedTask;
        }
    }

    public class Article
    {
        public int Id { get; set; }
        public string Title { get; set; }
        public string Content { get; set; }
        public string AuthorId { get; set; }
    }

    public static class ArticleOperations
    {
        public static OperationAuthorizationRequirement View =
            new OperationAuthorizationRequirement { Name = "View" };
        public static OperationAuthorizationRequirement Edit =
            new OperationAuthorizationRequirement { Name = "Edit" };
        public static OperationAuthorizationRequirement Delete =
            new OperationAuthorizationRequirement { Name = "Delete" };
    }

    // API 控制器
    [ApiController]
    [Route("api/[controller]")]
    public class AuthController : ControllerBase
    {
        private readonly JwtService _jwtService;

        public AuthController(JwtService jwtService)
        {
            _jwtService = jwtService;
        }

        [HttpPost("login")]
        public IActionResult Login([FromBody] LoginRequest request)
        {
            // 简化的用户验证
            var user = GetUser(request.Username, request.Password);
            if (user == null)
            {
                return Unauthorized(new { Message = "用户名或密码错误" });
            }

            var token = _jwtService.GenerateToken(user);
            return Ok(new { Token = token });
        }

        private User GetUser(string username, string password)
        {
            // 示例用户
            if (username == "admin" && password == "password")
            {
                return new User
                {
                    Id = 1,
                    Username = "admin",
                    Role = "Admin",
                    BirthDate = new DateTime(1990, 1, 1)
                };
            }
            return null;
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    public class ArticlesController : ControllerBase
    {
        private readonly IAuthorizationService _authorizationService;

        public ArticlesController(IAuthorizationService authorizationService)
        {
            _authorizationService = authorizationService;
        }

        [HttpGet("{id}")]
        [Authorize]
        public async Task<IActionResult> Get(int id)
        {
            var article = GetArticle(id);
            if (article == null)
            {
                return NotFound();
            }

            var authResult = await _authorizationService.AuthorizeAsync(
                User, article, ArticleOperations.View);

            if (!authResult.Succeeded)
            {
                return Forbid();
            }

            return Ok(article);
        }

        [HttpPut("{id}")]
        [Authorize]
        public async Task<IActionResult> Update(int id, [FromBody] Article article)
        {
            var existingArticle = GetArticle(id);
            if (existingArticle == null)
            {
                return NotFound();
            }

            var authResult = await _authorizationService.AuthorizeAsync(
                User, existingArticle, ArticleOperations.Edit);

            if (!authResult.Succeeded)
            {
                return Forbid();
            }

            // 更新文章
            return Ok(article);
        }

        private Article GetArticle(int id)
        {
            return new Article
            {
                Id = id,
                Title = "示例文章",
                Content = "文章内容",
                AuthorId = "1"
            };
        }
    }

    public class LoginRequest
    {
        public string Username { get; set; }
        public string Password { get; set; }
    }

    // 配置服务
    public static class AuthServiceCollectionExtensions
    {
        public static IServiceCollection AddCustomAuthentication(
            this IServiceCollection services,
            string jwtSecret,
            string jwtIssuer,
            string jwtAudience)
        {
            services.AddSingleton(new JwtService(jwtSecret, jwtIssuer, jwtAudience));

            services.AddAuthentication(options =>
            {
                options.DefaultAuthenticateScheme = JwtBearerDefaults.AuthenticationScheme;
                options.DefaultChallengeScheme = JwtBearerDefaults.AuthenticationScheme;
            })
            .AddJwtBearer(options =>
            {
                options.TokenValidationParameters = new TokenValidationParameters
                {
                    ValidateIssuer = true,
                    ValidateAudience = true,
                    ValidateLifetime = true,
                    ValidateIssuerSigningKey = true,
                    ValidIssuer = jwtIssuer,
                    ValidAudience = jwtAudience,
                    IssuerSigningKey = new SymmetricSecurityKey(
                        Encoding.UTF8.GetBytes(jwtSecret))
                };
            })
            .AddCookie(CookieAuthenticationDefaults.AuthenticationScheme, options =>
            {
                options.LoginPath = "/Account/Login";
                options.LogoutPath = "/Account/Logout";
            });

            services.AddAuthorization(options =>
            {
                options.AddPolicy("AtLeast18", policy =>
                    policy.Requirements.Add(new MinimumAgeRequirement(18)));

                options.AddPolicy("AdminOnly", policy =>
                    policy.RequireRole("Admin"));
            });

            services.AddSingleton<IAuthorizationHandler, MinimumAgeHandler>();
            services.AddSingleton<IAuthorizationHandler, ArticleOperationAuthorizationHandler>();

            return services;
        }
    }
}
